-- Initial schema for THE LORDS Finance OS, generated by `prisma migrate diff` from prisma/schema.prisma.
-- Hand-added security hardening (top and bottom of this file) so no table is ever reachable through
-- Supabase's API roles, not even between migrations: on Supabase, objects created by "postgres"
-- otherwise inherit full anon/authenticated privileges by default.

-- Security: stop new objects in "public" from inheriting privileges for the API roles.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon')
     AND EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
    ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON TABLES FROM anon, authenticated;
    ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON SEQUENCES FROM anon, authenticated;
    ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON FUNCTIONS FROM anon, authenticated;
  END IF;
END;
$$;

